class FoodScreen extends StatefulWidget{const FoodScreen({super.key});@override State<FoodScreen> createState()=>_FoodScreenState();}
class _FoodScreenState extends State<FoodScreen>{
 final ai=AiFoodService();final picker=ImagePicker();List<Meal> meals=[];List<WeightEntry> weights=[];Map<String,double>? goals;bool loading=true;String get today=>DateFormat('yyyy-MM-dd').format(DateTime.now());
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{meals=(await StorageService.read('meals')).map(Meal.fromJson).toList();weights=(await StorageService.read('body_weights')).map(WeightEntry.fromJson).toList()..sort((a,b)=>a.date.compareTo(b.date));final p=await SharedPreferences.getInstance();final g=p.getString('nutrition_goals')?.split('|');if(g!=null&&g.length==4)goals={'calories':double.tryParse(g[0])??0,'protein':double.tryParse(g[1])??0,'carbs':double.tryParse(g[2])??0,'fat':double.tryParse(g[3])??0};if(mounted)setState(()=>loading=false);if(goals==null&&mounted)WidgetsBinding.instance.addPostFrameCallback((_)=>_setup());}
 Future<void> _saveMeals()=>StorageService.write('meals',meals.map((e)=>e.toJson()).toList());Future<void> _saveWeights()=>StorageService.write('body_weights',weights.map((e)=>e.toJson()).toList());
 Future<void> _setup()async{final age=TextEditingController(),w=TextEditingController(),h=TextEditingController();String sex='Masculino',activity='Moderado',objective='Manter peso';final ok=await showDialog<bool>(context:context,barrierDismissible:false,builder:(c)=>StatefulBuilder(builder:(c,ss)=>AlertDialog(title:const Text('Configure suas metas'),content:SingleChildScrollView(child:Column(children:[TextField(controller:age,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Idade')),TextField(controller:w,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Peso (kg)')),TextField(controller:h,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Altura (cm)')),DropdownButtonFormField<String>(initialValue:sex,items:['Masculino','Feminino'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)ss(()=>sex=v);},decoration:const InputDecoration(labelText:'Sexo')),DropdownButtonFormField<String>(initialValue:activity,items:['Sedentário','Levemente ativo','Moderado','Muito ativo','Extremamente ativo'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)ss(()=>activity=v);},decoration:const InputDecoration(labelText:'Atividade')),DropdownButtonFormField<String>(initialValue:objective,items:['Perder peso','Manter peso','Ganhar peso'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)ss(()=>objective=v);},decoration:const InputDecoration(labelText:'Objetivo')),const SizedBox(height:8),const Text('As metas são estimativas e não substituem orientação profissional.',style:TextStyle(fontSize:12))])),actions:[FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Calcular'))])));if(ok!=true)return;final av=double.tryParse(age.text.replaceAll(',','.')),wv=double.tryParse(w.text.replaceAll(',','.')),hv=double.tryParse(h.text.replaceAll(',','.'));if(av==null||wv==null||hv==null||av<=0||wv<=0||hv<=0){_msg('Preencha os dados corretamente.');return;}const factors={'Sedentário':1.2,'Levemente ativo':1.375,'Moderado':1.55,'Muito ativo':1.725,'Extremamente ativo':1.9};final bmr=sex=='Masculino'?10*wv+6.25*hv-5*av+5:10*wv+6.25*hv-5*av-161;final kcal=bmr*factors[activity]!+(objective=='Perder peso'?-400:objective=='Ganhar peso'?300:0);final protein=wv*2;final fat=kcal*.27/9;final carbs=(kcal-protein*4-fat*9)/4;goals={'calories':kcal,'protein':protein,'carbs':carbs,'fat':fat};final p=await SharedPreferences.getInstance();await p.setString('nutrition_goals','$kcal|$protein|$carbs|$fat');if(weights.every((x)=>x.date!=today)){weights.add(WeightEntry(date:today,weight:wv));await _saveWeights();}if(mounted)setState((){});}
 Future<void> _weight()async{final c=TextEditingController();final old=weights.where((x)=>x.date==today).toList();if(old.isNotEmpty)c.text=old.first.weight.toString();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Peso de hoje'),content:TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(suffixText:'kg')),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Salvar'))]));final v=double.tryParse(c.text.replaceAll(',','.'));if(ok!=true||v==null||v<=0)return;weights.removeWhere((x)=>x.date==today);weights.add(WeightEntry(date:today,weight:v));weights.sort((a,b)=>a.date.compareTo(b.date));await _saveWeights();if(mounted)setState((){});}
 Future<void> _manual()async{final n=TextEditingController(),q=TextEditingController(),k=TextEditingController(),p=TextEditingController(),c=TextEditingController(),f=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Adicionar refeição'),content:SingleChildScrollView(child:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Alimento')),TextField(controller:q,decoration:const InputDecoration(labelText:'Quantidade')),TextField(controller:k,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Calorias')),TextField(controller:p,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Proteína (g)')),TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Carboidratos (g)')),TextField(controller:f,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Gorduras (g)'))])),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Adicionar'))]));if(ok==true&&n.text.trim().isNotEmpty){meals.add(Meal(id:DateTime.now().microsecondsSinceEpoch.toString(),date:today,type:'Refeição',food:q.text.trim().isEmpty?n.text.trim():'${n.text.trim()} (${q.text.trim()})',calories:double.tryParse(k.text.replaceAll(',','.'))??0,protein:double.tryParse(p.text.replaceAll(',','.'))??0,carbs:double.tryParse(c.text.replaceAll(',','.'))??0,fat:double.tryParse(f.text.replaceAll(',','.'))??0));await _saveMeals();if(mounted)setState((){});}}
 Future<void> _textAI()async{final c=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Analisar por texto'),content:TextField(controller:c,maxLines:3,decoration:const InputDecoration(hintText:'Ex.: 150g arroz e 100g frango')),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Analisar'))]));if(ok!=true||c.text.trim().isEmpty)return;try{final r=await ai.estimateText(c.text);if(mounted)_result(r);}catch(e){_msg(e.toString());}}
 Future<void> _photo()async{final x=await picker.pickImage(source:ImageSource.camera,imageQuality:80);if(x==null)return;try{final r=await ai.estimateImage(x.path);if(mounted)_result(r);}catch(e){_msg(e.toString());}}
 Future<void> _result(FoodResult r)async{final add=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Estimativa nutricional'),content:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[...r.items.map((i)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(i.name),subtitle:Text('${i.grams.toStringAsFixed(0)}g • ${i.calories.toStringAsFixed(0)} kcal • P ${i.protein.toStringAsFixed(1)}g • C ${i.carbs.toStringAsFixed(1)}g • G ${i.fat.toStringAsFixed(1)}g'))),const Divider(),Text('${r.calories.toStringAsFixed(0)} kcal • P ${r.protein.toStringAsFixed(1)}g • C ${r.carbs.toStringAsFixed(1)}g • G ${r.fat.toStringAsFixed(1)}g'),const SizedBox(height:8),Text(r.note)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('NÃO CONTAR')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('CONTAR'))]));if(add==true){meals.add(Meal(id:DateTime.now().microsecondsSinceEpoch.toString(),date:today,type:'Refeição',food:r.items.map((i)=>i.name).join(', '),calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,source:'ai'));await _saveMeals();if(mounted)setState((){});}}
 void _msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final list=meals.where((x)=>x.date==today).toList();final kcal=list.fold(0.0,(s,x)=>s+x.calories);final protein=list.fold(0.0,(s,x)=>s+x.protein);final carbs=list.fold(0.0,(s,x)=>s+x.carbs);final fat=list.fold(0.0,(s,x)=>s+x.fat);final current=weights.isEmpty?null:weights.last;return SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(16,14,16,28),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Alimentação',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text('${list.length} refeição(ões) hoje')])),IconButton(onPressed:()=>_setup(),icon:const Icon(Icons.settings_outlined))]),const SizedBox(height:12),if(goals!=null)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Metas diárias',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),_bar('Calorias',kcal,goals!['calories']!,'kcal'),_bar('Proteína',protein,goals!['protein']!,'g'),_bar('Carboidratos',carbs,goals!['carbs']!,'g'),_bar('Gorduras',fat,goals!['fat']!,'g')])),AppCard(child:Row(children:[const Icon(Icons.monitor_weight_outlined,size:32),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Peso corporal'),Text(current==null?'—':'${current.weight.toStringAsFixed(1)} kg',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold))])),OutlinedButton(onPressed:_weight,child:const Text('Registrar'))])),if(weights.length>=2)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Evolução do peso',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),SizedBox(height:90,child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:weights.take(12).map((x)=>Expanded(child:Padding(padding:const EdgeInsets.symmetric(horizontal:2),child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[Text(x.weight.toStringAsFixed(1),style:const TextStyle(fontSize:10)),const SizedBox(height:3),Container(height:(x.weight/100*70).clamp(8.0,70.0),decoration:BoxDecoration(color:Theme.of(context).colorScheme.primary,borderRadius:BorderRadius.circular(4)))]))).toList()))])),Row(children:[Expanded(child:FilledButton.icon(onPressed:_textAI,icon:const Icon(Icons.auto_awesome),label:const Text('Analisar texto'))),const SizedBox(width:8),IconButton.filled(onPressed:_photo,icon:const Icon(Icons.camera_alt_outlined))]),const SizedBox(height:8),FilledButton.tonalIcon(onPressed:_manual,icon:const Icon(Icons.add),label:const Text('Adicionar manualmente')),const SizedBox(height:12),Text('Refeições de hoje',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),if(list.isEmpty)const AppCard(child:Text('Nenhuma refeição registrada.')),...list.map((m)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,title:Text(m.food),subtitle:Text('${m.calories.toStringAsFixed(0)} kcal • P ${m.protein.toStringAsFixed(1)}g • C ${m.carbs.toStringAsFixed(1)}g • G ${m.fat.toStringAsFixed(1)}g'),trailing:IconButton(onPressed:()async{meals.remove(m);await _saveMeals();if(mounted)setState((){});},icon:const Icon(Icons.delete_outline))))]));}
 Widget _bar(String n,double v,double g,String u){final p=g<=0?0.0:(v/g).clamp(0.0,1.0).toDouble();return Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(n)),Text('${v.toStringAsFixed(0)} / ${g.toStringAsFixed(0)} $u')]),const SizedBox(height:3),LinearProgressIndicator(value:p,minHeight:7)]));}
